1103		dir := t.TempDir()
1104		report := Report{
1105			Artifact: ReportArtifact{Name: "Vault", Hash: ArtifactHash(sampleArtifact())},
1106			Rules: []ReportRule{
1107				{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1", Status: StatusDefect, Note: "counterexample"},
1108			},
1109			Findings: []ReportFinding{
1110				{ArtifactHash: ArtifactHash(sampleArtifact()), RuleID: "r1", Version: "9.9.9", Severity: "high", Invariant: "inv", Evidence: "counterexample"},
1111			},
1112		}
