1120		if !errors.As(err, &ec) {
1121			t.Fatalf("expected errCorrupt, got %T: %v", err, err)
1122		}
1123	}
1124	
1125	func TestSaveReportPermutationKeepsFirstBytes(t *testing.T) {
1126		dir := t.TempDir()
1127		rules := sampleRules()
1128		r1, err := BuildReport(sampleArtifact(), rules, sampleInvariants(), nil)
1129		if err != nil {
1130			t.Fatal(err)
1131		}
1132		if err := SaveReport(dir, r1); err != nil {
1133			t.Fatal(err)
1134		}
1135		path := filepath.Join(dir, r1.ReportID+".json")
1136		first, _ := os.ReadFile(path)
1137		r2, err := BuildReport(sampleArtifact(), []Rule{rules[2], rules[0], rules[1]}, sampleInvariants(), nil)
1138		if err != nil {
1139			t.Fatal(err)
