	errs := make(chan error, 16)
	for i := 0; i < 16; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			errs <- SaveReport(dir, report)
		}()
	}
	wg.Wait()
	close(errs)
	for err := range errs {
