// expectCorruptLoad writes the archive, loads it and asserts the read is
// rejected as a corrupt archive: errCorrupt (not errInvalid/errNotFound), no
// report returned, and the message names the involved rule.
func expectCorruptLoad(t *testing.T, dir, id, rule string, r Report) {
	t.Helper()
	got, err := LoadReport(dir, id)
	if err == nil {
		t.Fatalf("expected corrupt rejection, load succeeded: %+v", got)
	}
	var ec errCorrupt
	if !errors.As(err, &ec) {
		t.Fatalf("expected errCorrupt, got %T: %v", err, err)
	}
	if rule != "" && !strings.Contains(err.Error(), rule) {
		t.Fatalf("error must name involved rule %q: %v", rule, err)
	}
}

// assertArchiveUntouched verifies a failed/successful read never rewrites the
// archive: file set and bytes for id are unchanged from wantBytes.
func assertArchiveUntouched(t *testing.T, dir, id string, wantBytes []byte) {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(dir, id+".json"))
	if err != nil {
		t.Fatalf("archive must still exist after read: %v", err)
	}
	if string(data) != string(wantBytes) {
		t.Fatal("read modified the archive bytes")
	}
}

// storeAndCorrupt writes r with a fresh matching id, then applies mutate to the
// decoded on-disk report and rewrites it with ANOTHER fresh id, renaming the
// file so the request id matches the final content. The result is an archive
// whose id matches its (corrupt) content exactly.
func storeAndCorrupt(t *testing.T, dir string, r Report, mutate func(*Report)) string {
	t.Helper()
	id := writeReportWithFreshID(t, dir, r)
	path := filepath.Join(dir, id+".json")
	var stored Report
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &stored); err != nil {
		t.Fatal(err)
	}
	mutate(&stored)
	stored.ReportID = ReportID(stored)
	out, err := json.Marshal(stored)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(path); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, stored.ReportID+".json"), out, 0o644); err != nil {
		t.Fatal(err)
	}
	return stored.ReportID
}

// --- 损坏归属：同一条缺陷被重复列出 ---

func TestLoadReportRejectsDuplicateFinding(t *testing.T) {
	dir := t.TempDir()
	report := oneDefectFixture()
	id := storeAndCorrupt(t, dir, report, func(stored *Report) {
		f := stored.Findings[0]
		stored.Findings = append(stored.Findings, f) // same rule twice
	})
	expectCorruptLoad(t, dir, id, "r-bad", report)
}

// --- 损坏归属：缺陷引用不存在的规则 ---

func TestLoadReportRejectsFindingForUnknownRule(t *testing.T) {
