		// r-pass is 通过; move the finding onto it and clear r-bad's defect by
		// turning it 通过 as well, so the only defect claim is the illegal one.
		stored.Findings[0].RuleID = "r-pass"
		for i := range stored.Rules {
			if stored.Rules[i].ID == "r-bad" {
				stored.Rules[i].Status = StatusPass
				stored.Rules[i].Note = ""
			}
